  POLL_MS,
  RETRY_DELAY_MS,
  STEP_MS,
  type JobRow,
} from './jobs.ts';

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// Claims the oldest job that is either queued and due, or running with an expired lease (its
// worker died). Claiming a queued job starts a new attempt (attempts + 1). Reclaiming an expired
// running job re-runs the attempt that was already counted when it started, so attempts never
// exceeds MAX_ATTEMPTS. Progress is reset in the same atomic statement.
const claimJob = db.prepare(`
  UPDATE jobs
  SET status = 'running',
      attempts = attempts + CASE WHEN status = 'queued' THEN 1 ELSE 0 END,
      progress_completed = 0,
      lease_until = ?,
      updated_at = ?
  WHERE seq = (
    SELECT seq FROM jobs
    WHERE (status = 'queued' AND run_after <= ?) OR (status = 'running' AND lease_until < ?)
    ORDER BY seq
    LIMIT 1
  )
  RETURNING *
`);
const recordProgress = db.prepare(`
  UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?
`);
const completeJob = db.prepare(`
  UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, lease_until = 0, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?
`);
const requeueJob = db.prepare(`
  UPDATE jobs SET status = 'queued', run_after = ?, lease_until = 0, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?
`);
const failJob = db.prepare(`
  UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, lease_until = 0, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?
`);
// On a graceful stop the in-flight attempt is abandoned: the job goes back to queued and the
// attempt it started is undone, so the restarted worker runs it as the same attempt number.
const abortJob = db.prepare(`
  UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0,
                  run_after = 0, lease_until = 0, updated_at = ?
  WHERE id = ? AND status = 'running' AND attempts = ?
`);
const upsertHeartbeat = db.prepare(`
  INSERT INTO meta (key, value) VALUES ('worker_heartbeat', ?)
  ON CONFLICT(key) DO UPDATE SET value = excluded.value
`);
const deleteHeartbeat = db.prepare("DELETE FROM meta WHERE key = 'worker_heartbeat'");

let lastBeat = 0;
function beatIfDue(): void {
  const now = Date.now();
  if (now - lastBeat < HEARTBEAT_INTERVAL_MS) return;
  upsertHeartbeat.run(now);
  lastBeat = now;
}

function claim(): JobRow | undefined {
  const now = Date.now();
  return claimJob.get(now + LEASE_MS, new Date(now).toISOString(), now, now) as unknown as JobRow | undefined;
}

/** Renews the lease and records progress for the attempt; returns false if the attempt was taken over. */
function heartbeatAttempt(job: JobRow, attempt: number, progress: number): boolean {
  const now = Date.now();
  return recordProgress.run(progress, now + LEASE_MS, new Date(now).toISOString(), job.id, attempt).changes === 1;
}

/**
 * Runs one attempt of a claimed job. Every write is conditioned on the attempt number, so a
 * stale worker cannot overwrite a job that was reclaimed by another attempt.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: the attempt fails at its first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return abortAttempt(job, attempt);
    if (!heartbeatAttempt(job, attempt, 0)) return;
    if (attempt >= MAX_ATTEMPTS) {
      failJob.run(new Date().toISOString(), job.id, attempt);
    } else {
      requeueJob.run(Date.now() + RETRY_DELAY_MS, new Date().toISOString(), job.id, attempt);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return abortAttempt(job, attempt);
    beatIfDue();
    if (!heartbeatAttempt(job, attempt, step)) return; // Taken over elsewhere.
  }

  completeJob.run(job.input.toUpperCase(), new Date().toISOString(), job.id, attempt);
}

function abortAttempt(job: JobRow, attempt: number): void {
  abortJob.run(new Date().toISOString(), job.id, attempt);
}

console.log('worker started');
while (!stopping) {
  try {
    beatIfDue();
    const job = claim();
    if (job) {
      await runAttempt(job);
    } else {
      await sleep(POLL_MS);
    }
  } catch (e) {
    console.error('worker error:', e);
    await sleep(POLL_MS);
  }
}

deleteHeartbeat.run();
db.close();
console.log('worker stopped');

